mapper.select:
select * from ( select aaa.effectiveStatusName, aaa.entrustStatus, aaa.execFinishAmt, aaa.execRemainderAmt, aaa.execProcess, aaa.transFinishAmt, aaa.transRemainderAmt, aaa.transProcess, aaa.firstBidStatus, aaa.finprodId, aaa.finprodMarketId, aaa.finprodAbbr, aaa.issueClass, aaa.tradeMarket, aaa.ps, aaa.issueDateStart, aaa.issueDateEnd, aaa.totalBiddingNum, aaa.bidPriceStr, aaa.payEdate, aaa.portfolioId, aaa.portfolioName, aaa.busiModel, aaa.invManagerId, aaa.entrustId, aaa.etrDate, aaa.counterId, aaa.counterName, aaa.approver, aaa.remark, aaa.payEdateStr, aaa.etrDateStr, TO_CHAR(aaa.issueDateStart, 'yyyy-MM-dd') || '~' || TO_CHAR(aaa.issueDateEnd, 'yyyy-MM-dd') issueDateStr
from (
UNION ALL
) aaa left join SYS_DATADICT_LIST sdl on aaa.entrustStatus=sdl.ITEM_CODE and sdl.DICT_CODE='ENTRUST_STATUS' left join SYS_DATADICT_LIST issueClassSdl on aaa.issueClass = issueClassSdl.ITEM_CODE and issueClassSdl.DICT_CODE='ISSUE_CLASS' left join SYS_DATADICT_LIST bidStatusSdl on aaa.firstBidStatus = bidStatusSdl.ITEM_CODE and bidStatusSdl.DICT_CODE='FIRST_BID_STATUS' left join SYS_DATADICT_LIST dictbusiModel on aaa.busiModel=dictbusiModel.ITEM_CODE and dictbusiModel.DICT_CODE='BUSINESS_MODEL' left join SYS_DATADICT_LIST tradeMarketSdl on aaa.tradeMarket=tradeMarketSdl.ITEM_CODE and tradeMarketSdl.DICT_CODE='TRADE_PLACE'
AND aaa.issueDateStart >= to_date(#{issueDateStart}, 'yyyy-MM-dd') AND aaa.issueDateEnd <= to_date(#{issueDateEnd}, 'yyyy-MM-dd')
AND
(INSTR(aaa.portfolioId,concat(#{item},','))>0 OR INSTR(aaa.portfolioId,concat(#{item},','))>0 OR aaa.portfolioId = #{item} )
AND aaa.firstBidStatus = #{firstBidStatus}
order by sdl.ORDER_NO, aaa.entrustId DESC)
order by ${pageMode.sort} ${pageMode.direction}

sql.if:
AND (
aaa.effectiveStatusName || '|' || sdl.ITEM_VALUE || '|' || bidStatusSdl.ITEM_VALUE || '|' || aaa.portfolioId || '|' || aaa.portfolioName
|| '|' || issueClassSdl.ITEM_VALUE || '|' || aaa.finprodMarketId || '|' || aaa.finprodAbbr || '|' || aaa.invManagerId
|| '|' || aaa.entrustId || '|' || approver || '|' || aaa.REMARK || '|' || dictbusiModel.ITEM_VALUE
|| '|' || aaa.counterId || '|' || aaa.counterName || '|' || tradeMarketSdl.ITEM_VALUE || '|' || TO_CHAR(aaa.issueDateStart, 'yyyy-MM-dd') || '~' || TO_CHAR(aaa.issueDateEnd, 'yyyy-MM-dd')
like '%' || #{search} || '%'
or to_char(aaa.execProcess,'FM99990.9990')=#{search} or  aaa.execProcess||'' =#{search}
or to_char(aaa.transProcess,'FM99990.9990')=#{search} or  aaa.transProcess||'' =#{search}
or to_char(aaa.etrDate,'yyyy-MM-dd')  = #{search}
or to_char(aaa.etrDate,'yyyyMMdd')  = #{search}
or to_char(aaa.etrDate,'yyyy-MM-dd') =#{year}||'-'||#{search}
or to_char(aaa.etrDate,'yyyyMMdd') =#{year}||''||#{search}
or to_char(aaa.issueDateStart,'yyyy-MM-dd')  = #{search}
or to_char(aaa.issueDateStart,'yyyyMMdd')  = #{search}
or to_char(aaa.issueDateEnd,'yyyy-MM-dd')  = #{search}
or to_char(aaa.issueDateEnd,'yyyyMMdd')  = #{search}
or aaa.totalBiddingNum || ''= #{search}
or aaa.bidPriceStr = #{search}
or TO_CHAR(aaa.issueDateStart, 'yyyy-MM-dd') || '~' || TO_CHAR(aaa.issueDateEnd, 'yyyy-MM-dd') = #{search}
or to_char(aaa.payEdate,'yyyy-MM-dd')  = #{search}
or to_char(aaa.payEdate,'yyyyMMdd')  = #{search}
)

mapper.sql:
SELECT decode(ee.ENTRUST_STATUS,'08','流程中','有效') AS effectiveStatusName, ee.ENTRUST_STATUS entrustStatus, trunc(nvl(efs.ENT_FINISH_AMT, 0)/10000, 2) execFinishAmt, trunc((nvl(ee.ENTRUST_NUM*100,0) - nvl(efs.ENT_FINISH_AMT, 0))/10000,2) execRemainderAmt, trunc(nvl(efs.ENT_FINISH_AMT, 0) / case when ee.ENTRUST_NUM is null or ee.ENTRUST_NUM = 0 then 1 else ee.ENTRUST_NUM*100 end, 4) * 100 execProcess, trunc(nvl(tpd.SHARE_AMT * 100, 0)/10000,2) transFinishAmt, trunc((nvl(ee.ENTRUST_NUM*100,0) - nvl(tpd.SHARE_AMT * 100, 0))/10000,2) transRemainderAmt, trunc(nvl(tpd.SHARE_AMT * 100, 0) / case when ee.ENTRUST_NUM is null or ee.ENTRUST_NUM = 0 then 1 else ee.ENTRUST_NUM*100 end, 4) * 100 transProcess, CASE WHEN fpi.ISSUE_CLASS = '01' THEN NULL WHEN (bobrt.BID_MODLE IS NOT NULL AND bobrt.BID_MODLE = '03') OR bobrt.IS_WIN = '04' THEN '04' WHEN bobrt.BID_MODLE IS NULL THEN '01' WHEN bobrt.IS_WIN = '03' THEN '03' WHEN (bobrt.BID_MODLE IN ('01', '02') AND bobrt.IS_WIN IS NULL) THEN '02' ELSE '05' END AS firstBidStatus, ee.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr, fpi.ISSUE_CLASS issueClass, ee.TRADE_MARKET tradeMarket, ee.PS ps, CASE WHEN fpi.ISSUE_CLASS IN ('02', '03') THEN nvl(fpi.ISSUE_DATE, fpi.TENDER_SDATE) ELSE fpi.ISSUE_DATE END AS issueDateStart, CASE WHEN fpi.ISSUE_CLASS IN ('02', '03') THEN nvl(fpi.ISSUE_DATE, fpi.TENDER_EDATE) ELSE fpi.ISSUE_DATE END AS issueDateEnd, ee.ENTRUST_NUM/100 totalBiddingNum, CASE WHEN fpi.ISSUE_CLASS = '01' THEN CASE WHEN fp.COUPON_SPECIES = '01' AND fpi.INT_TYPE = '02' THEN SDLDATA.ITEM_VALUE || '+' || to_char(fpi.bp * 10000 , 'FM9999999999999990.90') || ' BP' ELSE to_char(fpi.REFER_YIELD * 100 , 'FM9999999999999990.9990') || ' %' END WHEN fpi.TENDER_TARGET = '01' THEN bobp.BID_PRICE || ' %' WHEN fpi.TENDER_TARGET = '02' THEN bobp.BID_PRICE || ' 元' WHEN fpi.TENDER_TARGET = '03' THEN bobp.BID_PRICE || ' BP' ELSE bobp.BID_PRICE END AS bidPriceStr, CASE WHEN fpi.ISSUE_CLASS IN ('02', '03') THEN fpi.PAY_EDATE ELSE fpi.PAY_DATE END AS payEdate, T2.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T2.INV_AIM busiModel, T8.REAL_NAME invManagerId, ee.ENTRUST_ID entrustId, ee.ENTRUST_DATE AS etrDate, ee.COUNTER_ID counterId, mcp.COUNTER_NAME counterName, NULL AS approver, ee.REMARK remark, CASE WHEN fpi.ISSUE_CLASS IN ('02', '03') THEN TO_CHAR(fpi.PAY_EDATE, 'yyyy-MM-dd') ELSE TO_CHAR(fpi.PAY_DATE, 'yyyy-MM-dd') END AS payEdateStr, TO_CHAR(ee.ENTRUST_DATE, 'yyyy-MM-dd') as etrDateStr
FROM ETR_ENTRUST ee LEFT JOIN (select ENTRUST_ID ,PORTFOLIO_ID from(select ol.ENTRUST_ID,ol.PORTFOLIO_ID, row_number() OVER(PARTITION BY ol.ENTRUST_ID ORDER BY ol.ENTRUST_ID) ds from ETR_ENTRUST_DETAIL ol where ol.ENTRUST_ID is not null) where ds = 1 ) det2 ON det2.ENTRUST_ID = ee.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON det2.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = ee.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD fpa ON fpa.FINPROD_ID = ee.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE fpi ON fpi.FINPROD_ID = fp.FINPROD_ID LEFT JOIN (select * from SYS_DATADICT_LIST where DICT_CODE='SECRATE_DATA') SDLDATA on fpi.INT_RATE_ID = SDLDATA.ITEM_CODE left join (select sum(ENT_FINISH_AMT) ENT_FINISH_AMT, sum(FINISH_AMT) FINISH_AMT, ENTRUST_ID from ETR_FINISH_STATUS group by ENTRUST_ID) efs on ee.ENTRUST_ID = efs.ENTRUST_ID left join (select sum(t1.SHARE_AMT) SHARE_AMT, t2.ENTRUST_ID from TRD_PRODUCT_DEAL t1 left join TRD_PRODUCT_DEAL_ADD t2 on t1.TRADE_ID = t2.TRADE_ID where t1.IS_CANCEL = 'N' and t1.TRADE_STATUS != '03' group by t2.ENTRUST_ID) tpd on tpd.ENTRUST_ID = ee.ENTRUST_ID LEFT JOIN MST_COUNTER_PARTY mcp ON mcp.COUNTER_ID = ee.COUNTER_ID LEFT JOIN (select listagg(case when t3.TENDER_TARGET = '01' then to_char(t0.BID_PRICE * 100, 'FM9999999999999990.9990') when t3.TENDER_TARGET = '02' then to_char(t0.BID_PRICE, 'FM9999999999999990.9990') when t3.TENDER_TARGET = '03' then to_char(t0.BID_PRICE * 10000, 'FM9999999999999990.90') end, ',') within group (order by t0.ENTRUST_ID) AS BID_PRICE, t0.ENTRUST_ID from ETR_ENTRUST_BID_PRICE t0 LEFT JOIN ETR_ENTRUST t1 on t1.ENTRUST_ID = t0.ENTRUST_ID LEFT JOIN FIN_PRODUCT t2 ON t2.FINPROD_ID = t1.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE t3 ON t3.FINPROD_ID = t2.FINPROD_ID group by t0.ENTRUST_ID) bobp ON bobp.ENTRUST_ID = ee.ENTRUST_ID LEFT JOIN ( SELECT bo.BID_MODLE, brt.IS_WIN ,bo.FINPROD_ID FROM BID_ORDER bo LEFT JOIN BID_RESULT_TOTAL brt ON brt.BID_ID = bo.BID_ID AND brt.STATUS = '01' AND brt.FINPROD_ID = bo.FINPROD_ID WHERE bo.IS_CANCEL = 'N' AND bo.TRADE_STATUS = '01' GROUP BY bo.BID_MODLE, brt.IS_WIN, bo.FINPROD_ID ) bobrt ON bobrt.FINPROD_ID = fp.FINPROD_ID LEFT JOIN ( SELECT LISTAGG(eed.PORTFOLIO_ID, ',') WITHIN GROUP (ORDER BY (eed.PORTFOLIO_ID)) PORTFOLIO_ID, LISTAGG(pp.PORTFOLIO_NAME , ',') WITHIN GROUP (ORDER BY (pp.PORTFOLIO_NAME)) PORTFOLIO_NAME, LISTAGG(eed.INV_AIM, ',') WITHIN GROUP (ORDER BY (eed.INV_AIM)) INV_AIM, eed.ENTRUST_ID ENTRUST_ID FROM ETR_ENTRUST_DETAIL eed LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = eed.PORTFOLIO_ID GROUP BY ENTRUST_ID ) T2 ON T2.ENTRUST_ID = ee.ENTRUST_ID LEFT JOIN SYS_USER T8 ON ee.INV_MANAGER_ID = T8.USER_NAME
WHERE ee.ENTRUST_NUM != 0 AND ee.ENTRUST_NUM IS NOT NULL AND ee.TRADE_MARKET IN ('01','02','03','04') AND ee.FINPROD_TYPE2 = #{FINPROD_TYPE2}
AND fp.FINPROD_ID in
#{item}
AND fpi.ISSUE_CLASS IN
#{item}
AND ee.INV_MANAGER_ID in
#{item}
AND (ee.ENTRUST_ID = #{entrustId} OR ee.ENTRUST_ID LIKE concat('%',concat(#{entrustId,jdbcType=VARCHAR},'%')) )
AND ee.ENTRUST_STATUS in
#{item}
AND ee.ENTRUST_DATE >= to_date(#{entrustStartDate}, 'yyyy-MM-dd') AND ee.ENTRUST_DATE <= to_date(#{entrustEndDate}, 'yyyy-MM-dd')
AND ee.COUNTER_ID in
#{item}

SELECT decode(ee.ENTRUST_STATUS,'08','流程中','有效') AS effectiveStatusName, ee.ENTRUST_STATUS entrustStatus, trunc(nvl(efs.ENT_FINISH_AMT, 0)/10000, 2) execFinishAmt, trunc((nvl(ee.ENTRUST_NUM*100,0) - nvl(efs.ENT_FINISH_AMT, 0))/10000,2) execRemainderAmt, trunc(nvl(efs.ENT_FINISH_AMT, 0) / case when ee.ENTRUST_NUM is null or ee.ENTRUST_NUM = 0 then 1 else ee.ENTRUST_NUM*100 end, 4) * 100 execProcess, trunc(nvl(tpd.SHARE_AMT * 100, 0)/10000,2) transFinishAmt, trunc((nvl(ee.ENTRUST_NUM*100,0) - nvl(tpd.SHARE_AMT * 100, 0))/10000,2) transRemainderAmt, trunc(nvl(tpd.SHARE_AMT * 100, 0) / case when ee.ENTRUST_NUM is null or ee.ENTRUST_NUM = 0 then 1 else ee.ENTRUST_NUM*100 end, 4) * 100 transProcess, CASE WHEN fpi.ISSUE_CLASS = '01' THEN NULL WHEN (bobrt.BID_MODLE IS NOT NULL AND bobrt.BID_MODLE = '03') OR bobrt.IS_WIN = '04' THEN '04' WHEN bobrt.BID_MODLE IS NULL THEN '01' WHEN bobrt.IS_WIN = '03' THEN '03' WHEN (bobrt.BID_MODLE IN ('01', '02') AND bobrt.IS_WIN IS NULL) THEN '02' ELSE '05' END AS firstBidStatus, ee.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr, fpi.ISSUE_CLASS issueClass, ee.TRADE_MARKET tradeMarket, ee.PS ps, CASE WHEN fpi.ISSUE_CLASS IN ('02', '03') THEN nvl(fpi.ISSUE_DATE, fpi.TENDER_SDATE) ELSE fpi.ISSUE_DATE END AS issueDateStart, CASE WHEN fpi.ISSUE_CLASS IN ('02', '03') THEN nvl(fpi.ISSUE_DATE, fpi.TENDER_EDATE) ELSE fpi.ISSUE_DATE END AS issueDateEnd, ee.ENTRUST_NUM/100 totalBiddingNum, CASE WHEN fpi.ISSUE_CLASS = '01' THEN CASE WHEN fp.COUPON_SPECIES = '01' AND fpi.INT_TYPE = '02' THEN SDLDATA.ITEM_VALUE || '+' || to_char(fpi.bp * 10000 , 'FM9999999999999990.90') || ' BP' ELSE to_char(fpi.REFER_YIELD * 100 , 'FM9999999999999990.9990') || ' %' END WHEN fpi.TENDER_TARGET = '01' THEN bobp.BID_PRICE || ' %' WHEN fpi.TENDER_TARGET = '02' THEN bobp.BID_PRICE || ' 元' WHEN fpi.TENDER_TARGET = '03' THEN bobp.BID_PRICE || ' BP' ELSE bobp.BID_PRICE END AS bidPriceStr, CASE WHEN fpi.ISSUE_CLASS IN ('02', '03') THEN fpi.PAY_EDATE ELSE fpi.PAY_DATE END AS payEdate, T2.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T2.INV_AIM busiModel, T8.REAL_NAME invManagerId, ee.ENTRUST_ID entrustId, ee.ENTRUST_DATE AS etrDate, ee.COUNTER_ID counterId, mcp.COUNTER_NAME counterName, nextUser.userName AS approver, ee.REMARK remark, CASE WHEN fpi.ISSUE_CLASS IN ('02', '03') THEN TO_CHAR(fpi.PAY_EDATE, 'yyyy-MM-dd') ELSE TO_CHAR(fpi.PAY_DATE, 'yyyy-MM-dd') END AS payEdateStr, TO_CHAR(ee.ENTRUST_DATE, 'yyyy-MM-dd') as etrDateStr
FROM WFL_ETR_ENTRUST ee LEFT JOIN (select ENTRUST_ID ,PORTFOLIO_ID from(select ol.ENTRUST_ID,ol.PORTFOLIO_ID, row_number() OVER(PARTITION BY ol.ENTRUST_ID ORDER BY ol.ENTRUST_ID) ds from WFL_ETR_ENTRUST_DETAIL ol where ol.ENTRUST_ID is not null) where ds = 1 ) det2 ON det2.ENTRUST_ID = ee.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON det2.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = ee.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD fpa ON fpa.FINPROD_ID = ee.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE fpi ON fpi.FINPROD_ID = fp.FINPROD_ID LEFT JOIN (select * from SYS_DATADICT_LIST where DICT_CODE='SECRATE_DATA') SDLDATA on fpi.INT_RATE_ID = SDLDATA.ITEM_CODE left join (select sum(ENT_FINISH_AMT) ENT_FINISH_AMT, sum(FINISH_AMT) FINISH_AMT, ENTRUST_ID from ETR_FINISH_STATUS group by ENTRUST_ID) efs on ee.ENTRUST_ID = efs.ENTRUST_ID left join (select sum(t1.SHARE_AMT) SHARE_AMT, t2.ENTRUST_ID from TRD_PRODUCT_DEAL t1 left join TRD_PRODUCT_DEAL_ADD t2 on t1.TRADE_ID = t2.TRADE_ID where t1.IS_CANCEL = 'N' and t1.TRADE_STATUS != '03' group by t2.ENTRUST_ID) tpd on tpd.ENTRUST_ID = ee.ENTRUST_ID LEFT JOIN MST_COUNTER_PARTY mcp ON mcp.COUNTER_ID = ee.COUNTER_ID LEFT JOIN (select listagg(case when t3.TENDER_TARGET = '01' then to_char(t0.BID_PRICE * 100, 'FM9999999999999990.9990') when t3.TENDER_TARGET = '02' then to_char(t0.BID_PRICE, 'FM9999999999999990.9990') when t3.TENDER_TARGET = '03' then to_char(t0.BID_PRICE * 10000, 'FM9999999999999990.90') end, ',') within group (order by t0.ENTRUST_ID) AS BID_PRICE, t0.ENTRUST_ID from WFL_ETR_ENTRUST_BID_PRICE t0 LEFT JOIN WFL_ETR_ENTRUST t1 on t1.ENTRUST_ID = t0.ENTRUST_ID LEFT JOIN FIN_PRODUCT t2 ON t2.FINPROD_ID = t1.FINPROD_ID LEFT JOIN FIN_PRODUCT_ISSUE t3 ON t3.FINPROD_ID = t2.FINPROD_ID group by t0.ENTRUST_ID) bobp ON bobp.ENTRUST_ID = ee.ENTRUST_ID LEFT JOIN ( SELECT bo.BID_MODLE, brt.IS_WIN ,bo.FINPROD_ID FROM WFL_BID_ORDER bo LEFT JOIN WFL_BID_RESULT_TOTAL brt ON brt.BID_ID = bo.BID_ID AND brt.STATUS = '01' AND brt.FINPROD_ID = bo.FINPROD_ID WHERE bo.IS_CANCEL = 'N' AND bo.TRADE_STATUS = '01' GROUP BY bo.BID_MODLE, brt.IS_WIN, bo.FINPROD_ID ) bobrt ON bobrt.FINPROD_ID = fp.FINPROD_ID LEFT JOIN ( SELECT LISTAGG(eed.PORTFOLIO_ID, ',') WITHIN GROUP (ORDER BY (eed.PORTFOLIO_ID)) PORTFOLIO_ID, LISTAGG(pp.PORTFOLIO_NAME , ',') WITHIN GROUP (ORDER BY (pp.PORTFOLIO_NAME)) PORTFOLIO_NAME, LISTAGG(eed.INV_AIM, ',') WITHIN GROUP (ORDER BY (eed.INV_AIM)) INV_AIM, eed.ENTRUST_ID ENTRUST_ID FROM WFL_ETR_ENTRUST_DETAIL eed LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = eed.PORTFOLIO_ID GROUP BY ENTRUST_ID ) T2 ON T2.ENTRUST_ID = ee.ENTRUST_ID LEFT JOIN SYS_USER T8 ON ee.INV_MANAGER_ID = T8.USER_NAME LEFT JOIN (SELECT nextApp.workFlowId, (SELECT listagg(SYS_USER.REAL_NAME, ',') within GROUP(ORDER BY SYS_USER.USER_NAME) FROM SYS_USER WHERE instr(','||nextApp.nowUserId||',' , ','||SYS_USER.USER_NAME||',') > 0) userName FROM ( SELECT DISTINCT CASE WHEN T.PROCESS_STATE = 'END' THEN NULL ELSE T.NEXT_USER END AS nowUserId, sdpm.Workflow_Id AS workFlowId FROM SYS_WFL_BUSINESS_LIST T INNER JOIN SYS_DATA_PROCESS_MARK sdpm ON sdpm.business_data_pk1=T.TRADE_ID WHERE EXISTS (SELECT 1 FROM SYS_WFL_BUSINESS_LIST A WHERE A.SEQ_NO = (SELECT MAX(B.SEQ_NO) FROM SYS_WFL_BUSINESS_LIST B WHERE A.WORKFLOW_ID = B.WORKFLOW_ID) AND T.SEQ_NO = A.SEQ_NO) AND T.PROCESS_STATE IN ('ING') AND T.BUSINESS_TYPE='ETR18') nextApp ) nextUser ON ee.Workflow_Id=nextUser.workFlowId WHERE ee.ENTRUST_NUM != 0 AND ee.ENTRUST_NUM IS NOT NULL AND ee.TRADE_MARKET IN ('01','02','03','04') AND ee.FINPROD_TYPE2 = #{FINPROD_TYPE2}
AND fp.FINPROD_ID in
#{item}
AND fpi.ISSUE_CLASS IN
#{item}
AND ee.INV_MANAGER_ID in
#{item}
AND (ee.ENTRUST_ID = #{entrustId} OR ee.ENTRUST_ID LIKE concat('%',concat(#{entrustId,jdbcType=VARCHAR},'%')) )
AND ee.ENTRUST_STATUS in
#{item}
AND ee.ENTRUST_DATE >= to_date(#{entrustStartDate}, 'yyyy-MM-dd') AND ee.ENTRUST_DATE <= to_date(#{entrustEndDate}, 'yyyy-MM-dd')
AND ee.COUNTER_ID in
#{item}

mapper.select:
SELECT DISTINCT businessModel
FROM (
    SELECT aaa.businessModel FROM (
        SELECT eed.INV_AIM AS businessModel, a.UPDATE_TIME AS updateTime
        FROM ETR_ENTRUST a
        LEFT JOIN ETR_ENTRUST_DETAIL eed ON a.ENTRUST_ID = eed.ENTRUST_ID
        WHERE 1= 1
          AND a.ENTRUST_STATUS  IN ('02', '03', '04', '08', '09')
          AND a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
          AND eed.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
          AND eed.INV_AIM IS NOT NULL
          AND a.entrust_date <= #{platDate}
        UNION
        SELECT eed.INV_AIM AS businessModel, a.UPDATE_TIME AS updateTime
        FROM WFL_ETR_ENTRUST a
        LEFT JOIN WFL_ETR_ENTRUST_DETAIL eed ON a.ENTRUST_ID = eed.ENTRUST_ID
        WHERE 1= 1
          AND a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
          AND eed.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
          AND eed.INV_AIM IS NOT NULL
          AND a.entrust_date <= #{platDate}
          ) aaa
         ORDER BY aaa.updateTime DESC
     )
WHERE rownum=1

select * from ( select aaa.issueStage, aaa.finprodMarketId, aaa.finprodAbbr, aaa.finprodId, aaa.issueClass, aaa.planIssueAmt, aaa.issueDateStart, aaa.issueDateEnd, aaa.payEdate, aaa.couponSpecies, aaa.intType, aaa.issuePrice, aaa.referYieldStr, aaa.firstConfirmDate, aaa.minPamt, aaa.maxPamt, aaa.tradeMarket, aaa.issuer, aaa.ccy, aaa.type9, aaa.type10, aaa.type11, aaa.remark, aaa.tenderType, aaa.issueStyle, aaa.issueDateStr, aaa.payEdateStr, aaa.firstConfirmDateStr from (
UNION
) aaa left join SYS_DATADICT_LIST sdl on aaa.issueClass = sdl.ITEM_CODE and sdl.DICT_CODE = 'ISSUE_CLASS' left join SYS_DATADICT_LIST sdl2 on aaa.couponSpecies = sdl2.ITEM_CODE and sdl2.DICT_CODE = 'COUPON_SPECIES' left join SYS_DATADICT_LIST sdl3 on aaa.intType = sdl3.ITEM_CODE and sdl3.DICT_CODE = 'INT_TYPE' left join SYS_DATADICT_LIST sdl4 on aaa.type9 = sdl4.ITEM_CODE and sdl4.DICT_CODE = 'CUSTOM_ASSET_TYPE_TWO' left join SYS_DATADICT_LIST sdl5 on aaa.type10 = sdl5.ITEM_CODE and sdl5.DICT_CODE = 'CUSTOM_ASSET_TYPE_THREE' left join SYS_DATADICT_LIST sdl6 on aaa.type11 = sdl6.ITEM_CODE and sdl6.DICT_CODE = 'CUSTOM_ASSET_TYPE_FOUR' left join SYS_DATADICT_LIST sdl7 on aaa.ccy = sdl7.ITEM_CODE and sdl7.DICT_CODE = 'CCY' LEFT JOIN SYS_DATADICT_LIST sdl8 ON aaa.tradeMarket = sdl8.ITEM_CODE AND sdl8.DICT_CODE = 'TRADE_PLACE'
AND aaa.finprodMarketId=#{finprodMarketId,jdbcType=VARCHAR}
AND aaa.issueClass=#{issueClass,jdbcType=VARCHAR}
AND aaa.couponSpecies=#{couponSpecies,jdbcType=VARCHAR}
AND aaa.intType=#{intType,jdbcType=VARCHAR}
AND aaa.type9 in
#{item}
AND aaa.type10 in
#{item}
AND aaa.type11 in
#{item}
AND aaa.ccy=#{ccy,jdbcType=VARCHAR}
AND aaa.tradeMarket=#{tradeMarket,jdbcType=VARCHAR}
AND aaa.finprodId in
#{item}
AND aaa.issueDateStart >= to_date(#{issueDateStart}, 'yyyy-MM-dd') AND aaa.issueDateEnd <= to_date(#{issueDateEnd}, 'yyyy-MM-dd')
AND aaa.issueStage in
#{item}
)
order by ${pageMode.sort} ${pageMode.direction}

select t.ACCT_NO, R.ACCT_NAME, t.PORTFOLIO_ID as parentId, v.SEC_ACCT_ID, v.TRADE_PLACE, t.CCY from PTL_CAPACCT_INFO t left join STL_SEC_ACCT_INFO v on t.ACCT_NO = v.TRD_ACCT_ID LEFT JOIN STL_CAPACCT_INFO R ON T.ACCT_NO = R.ACCT_NO AND T.CCY = R.CCY LEFT JOIN PTL_SEC_ACCT PSA ON v.SEC_ACCT_ID = PSA.ACCT_NO
t.ACCT_TYPE = 'A07'
and t.PORTFOLIO_ID = #{portfolioId} AND PSA.PORTFOLIO_ID = #{portfolioId}
and v.TRADE_PLACE = #{tradeMarket}
and t.ACCT_NO = #{acctNo}
and t.ACCT_NO = #{initValue}
AND t.ACCT_NO like concat('%',concat(#{search},'%'))
order by t.ACCT_NO
